#!/usr/bin/env python3
import types,sys,sqlite3,json
from pathlib import Path
pb=types.ModuleType("pseudobulk_contract")
exec(compile(bytes.fromhex(""),"bundled-pseudobulk-contract","exec"),pb.__dict__)
bc=types.ModuleType("research_b_counts");bc.pb=pb
previous_bc=sys.modules.get("research_b_counts");sys.modules["research_b_counts"]=bc
component=types.ModuleType("b_state_expression")
try:
    exec(compile(bytes.fromhex(""),"bundled-b-state-expression","exec"),component.__dict__)
finally:
    if previous_bc is None:sys.modules.pop("research_b_counts",None)
    else:sys.modules["research_b_counts"]=previous_bc

import os
OUTPUT_NAMES=['expression.tsv','gene-qc.tsv','column-qc.tsv','background.tsv','normalization.json']
def run():
    inputs=[Path(os.environ['AUTONOMICS_INPUT'+str(i)]) for i in range(11)]
    outputs=[Path(os.environ['AUTONOMICS_OUTPUT'+str(i)]) for i in range(5)]
    pb.require([p.name for p in outputs]==OUTPUT_NAMES and
        len({p.parent.absolute() for p in outputs})==1,'complete declared TPM ports in one private directory required')
    parent=outputs[0].parent.absolute()
    pb.require(all(p.is_absolute() and '..' not in p.parts for p in outputs) and parent!=Path('/'),
        'private absolute output paths without traversal required')
    pb.require(not any(os.path.lexists(p) for p in outputs),'output exists; refusing overwrite')
    pb.require(not any(p.is_symlink() for p in [parent,*parent.parents]),'symlink output ancestor')
    parent.mkdir(parents=True,exist_ok=True)
    bundle=parent/'.b-state-tpm-complete'
    pb.require(not os.path.lexists(bundle),'complete normalization bundle already exists')
    result=component.normalize(inputs[0],dict(zip(component.INPUTS,inputs[1:])),bundle)
    # Only a complete bundle is linked. Any port failure makes this entry fail,
    # so a container engine must reject publication. Never remove foreign ports.
    for target in outputs:os.link(bundle/target.name,target)
    print(json.dumps({'scope':result['scope'],'formal_authorized':False,'scientific_G0_granted':False}))
if __name__=='__main__':
    try:run()
    except (ValueError,KeyError,TypeError,OSError,sqlite3.Error,UnicodeError,pb.csv.Error,OverflowError) as e:
        print('BLOCKED: '+str(e),file=sys.stderr);raise SystemExit(2)
